import os, re, fnmatch
home=os.path.expanduser('~')
exclude_dirs={'.cache','.npm','.pnpm-store','.local/share/Trash','node_modules','.git','__pycache__','.venv','venv','dist','build'}
name_pats=['*.env','*.env.*','*config*','*settings*','*.yml','*.yaml','*.json','*.toml','*.ini','*.conf','*.properties','wp-config.php','database.php','prisma.schema','docker-compose*.yml','docker-compose*.yaml']
content_re=re.compile(r'(database_url|db_host|db_user|db_name|db_pass|db_password|database_host|database_user|database_name|connectionstring|connection_string|postgres://|postgresql://|mysql://|mongodb://|redis://|jdbc:|pghost|pguser|pgdatabase|mysql_host|mongo_uri|redis_url|sequelize|typeorm|datasource|prisma)',re.I)
secret_key_re=re.compile(r'(password|passwd|pwd|secret|token|key|uri|url|dsn|connection|string)',re.I)
assign_re=re.compile(r'(?i)^\s*([A-Za-z0-9_.-]*(?:password|passwd|pwd|secret|token|key|uri|url|dsn|connection|string|host|user|name|database)[A-Za-z0-9_.-]*)\s*([:=])\s*(.+)$')
url_cred_re=re.compile(r'([a-z][a-z0-9+.-]*://)([^\s/@:]+):([^\s/@]+)@',re.I)
found=[]
for root, dirs, files in os.walk(home):
    relroot=os.path.relpath(root, home)
    dirs[:] = [d for d in dirs if d not in exclude_dirs and os.path.join(relroot,d) not in exclude_dirs]
    for f in files:
        path=os.path.join(root,f)
        rel=os.path.relpath(path, home)
        if not any(fnmatch.fnmatch(f,p) or fnmatch.fnmatch(rel,p) for p in name_pats):
            continue
        try:
            st=os.stat(path)
            if st.st_size>1024*1024: continue
            with open(path,'rb') as fh: data=fh.read()
            if b'\x00' in data: continue
            text=data.decode('utf-8','ignore')
        except Exception:
            continue
        matches=[]
        for i,line in enumerate(text.splitlines(),1):
            if content_re.search(line):
                s=line.strip()
                s=url_cred_re.sub(r'\1<user>:<redacted>@',s)
                m=assign_re.match(s)
                if m:
                    k,op,v=m.groups()
                    # redact likely sensitive/connection values; leave simple host/user/name visible only if non-secret
                    if secret_key_re.search(k) or '://' in v or '@' in v:
                        s=f'{k}{op}<redacted>'
                    elif len(v)>120:
                        s=f'{k}{op}<redacted-long-value>'
                if len(s)>200: s=s[:197]+'...'
                matches.append((i,s))
                if len(matches)>=5: break
        if matches:
            found.append((rel,matches))

if not found:
    print('NO_MATCHES')
else:
    for rel,matches in sorted(found):
        print(f'FILE ~/{rel}')
        for i,s in matches:
            print(f'  L{i}: {s}')
PY
